def compute_gram_matrix(nderiv, G, w):
    if nderiv < 0:
        return -1
    elif G is None or w is None:
        return -2
    else:
        G_ptr = G[0]
        w_ptr = w[0]
        result = gsl.bspline_gram(nderiv, G_ptr, w_ptr)
        if result != 0:
            return result
        else:
            return 0

