class MedianAccumulator:
    def __init__(self, window_size):
        self.window_size = window_size
        self.data = np.zeros(window_size * 2)
        self.index = 0

    def insert(self, value):
        if self.index < self.window_size:
            self.data[self.index] = value
        else:
            self.data[window_size:] = self.data[:window_size]
            self.data[:self.index] = [value] + self.data[1:self.index].tolist()
            self.index = (self.index % 2 * self.window_size) + 1

    def compute_median(self):
        return np.median(self.data[:self.index])

def moving_median(data, window_size):
    median_acc = MedianAccumulator(window_size)
    medians = []

    for value in data:
        median_acc.insert(value)
        medians.append(str(median_acc.compute_median()))

    return medians

