class gsl_matrix_complex(ctypes.Structure):
    _fields_ = [('data', ctypes.POINTER(c_double*2)), ('size1', c_int), ('size2', c_int)]

def numpy_to_gsl_matrix_complex(np_array):
    result = gsl_matrix_complex()
    result.size1 = np_array.shape[0]
    result.size2 = np_array.shape[1]
    result.data = ctypes.cast((c_double*2)*np.array(np_array).flatten(), ctypes.POINTER(c_double*2))
    return result

class gsl_vector(ctypes.Structure):
    _fields_ = [('data', ctypes.POINTER(c_double)), ('size', c_int)]

def gsl_vector_to_numpy(gsl_vector, size):
    return np.array((c_double*size).from_address(gsl_vector.data), dtype=np.complex64).reshape(size, 1)

gsl.gsl_eigen_genherm.argtypes = [ctypes.POINTER(gsl_matrix_complex), ctypes.POINTER(gsl_matrix_complex)]

def compute_eigenvalues(A, B):
    A_gsl = numpy_to_gsl_matrix_complex(A.copy())
    B_gsl = numpy_to_gsl_matrix_complex(B.copy())
    gsl.gsl_eigen_genherm(A_gsl, B_gsl)
    result = np.zeros((A.shape[0], B.shape[1]), dtype=np.complex64)
    for i in range(result.shape[0]):
        for j in range(result.shape[1]):
            try:
                result[i][j] = gsl_vector_to_numpy(gsl.gsl_eigen_genherm.eigenvecs[i].data, A.shape[0]).flatten()[j]
            except AttributeError as e:
                print(f"Error: {e}")
    return result

