    def generate_sobol_sequence(self, dimension, count):
        seq = array(ctypes.c_double, [0.0] * (dimension * count))
        seq_ptr = seq.ctypes.data_as(self.dbl_ptr)
        self.gsl_qrng_sobol_mt19937_init(self)
