        self.gsl_qrng_sobol_sequence_alloc(self, dimension, count)
        for i in range(count):
            self.gsl_qrng_sobol_get_sequence(self, seq_ptr, i * dimension, (dimension - 1))
        self.gsl_qrng_sobol_free(self)
        return [tuple(seq[i:i+dimension]) for i in range(0, count*dimension, dimension)]

