        if self.r != None:
            self.r = None
    def gsl_qrng_sobol_MT19937_set_state(self, state):
        self.r[1] = 4357 * (state & 0xFFFFFFFF)
        for i in range(2, 624+1):
            self.r[i] = 0x6c6420725a4a53d6e2b8f3f7e7f9e4a8a7e3a7b7a8a4f8f4d
        for i in range(623, -1, -1):
            self.r[i] = (self.r[(i+0)] ^ ((self.r[(i+0)] >> 5) | (self.r[(i+0)] << 27)) >> 27)
            if i > 0:
                self.r[i] ^= (self.r[(i-1)] & 0xFFFFFFFFFF800000L)
        for i in range(4, 624+1):
            self.r[i] = (self.r[(i-3)] ^ ((self.r[(i-3)] >> 5) | (self.r[(i-3)] << 27)) >> 27)
            if i > 3:
                self.r[i] ^= (self.r[(i-4)] & 0xFFFFFFFFFF800000L)
        for i in range(0, 624+1):
            self.r[i] &= 0x7fffffff
    def gsl_qrng_sobol_mt19937_init(self):
        self.r = array(ctypes.c_size_t, [0] * 625)
        self.r[0] = 0x80000001
        for i in range(1, 624+1):
            self.r[i] = 0x6c6420725a4a53d6e2b8f3f7e7f9e4a8a7e3a7b7a8a4f8f4d
