def write_and_read_permutation(perm_list):
    perm = gsl_permutation()
    perm.data = (c_int * len(perm_list)).from_buffer_copy(perm_list)
    file_descriptor = open("permutation.txt", "wb")
    try:
        gsl.gsl_permutation_fwrite(file_descriptor, perm)
    except RuntimeError as e:
        return {"error": str(e)}
    finally:
        file_descriptor.close()

    file_descriptor = open("permutation.txt", "rb")
    try:
        result = (c_int * len(perm_list)).from_buffer_copy(gsl.gsl_permutation_fread(file_descriptor, perm))
    except RuntimeError as e:
        return {"error": str(e)}
    finally:
        file_descriptor.close()

    if perm.data.contents == result:
        return json.dumps({"success": "Permutation read back successfully"})
    else:
        return json.dumps({"error": "Permutation does not match the input"})

