import numpy as np

def generate_reverse_halton(dimension, num_points):
    ctypes.CDLL(\"/usr/local/gsl/lib/libgslcblas.so\", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL(\"/usr/local/gsl/lib/libgsl.so\")

    from ctypes import c_int, c_double
    from ctypes import CDLL

    class Vector:
        def __init__(self):
            self.size = 0
            self.array = None

        def resize(self, size):
            if self.size >= size:
                return

            self.size = size
            self.array = (c_double * size).from_address(ctypes.cast(None, ctypes.POINTER(c_double)).value)

        def __getitem__(self, index):
            if not 0 <= index < self.size:
                raise IndexError(\"Index out of bounds\")
            return self.array[index]

        def __setitem__(self, index, value):
            if not 0 <= index < self.size:
                raise IndexError(\"Index out of bounds\")
            self.array[index] = value

    class Halton:
        def __init__(self, dimension):
            self.dimension = dimension
            self.base = [2, 3]
            self.prime = [1, 3, 4, 7, 13, 19, 31, 61, 97, 127]

            for i in range(dimension):
                if self.prime[i] > self.base[i]:
                    self.prime.pop(i)
                    self.base.pop(i)
                    self.dimension = i
                    break

        def next(self):
            vector = Vector()
            vector.resize(self.dimension)
            base_index = 0

            for i in range(self.dimension):
                if self.prime[i] > len(str(self.next_base(i))):
                    return None

                value = int(str(self.next_base(i)), self.base[i])

                for j in range(len(str(value))):
                    digit = (value // pow(self.base[i], len(str(value)) - 1 - j)) % self.base[i]

                    if digit == 0:
                        break
                    else:
                        value //= pow(self.base[i], len(str(value)) - 1 - j)

                vector.array[base_index] = float(digit) / self.prime[i]
                base_index += 1

            return vector

        def next_base(self, index):
            result = 0
            while True:
                if not (self.base[index] <= self.prime[index]):
                    break
                remainder = self.prime[index] % self.base[index]
                self.prime[index] //= self.base[index]

                if remainder > 0:
                    return remainder
                else:
                    self.prime.pop(index)
                    self.base.pop(index)

                    if not self.prime:
                        return None
                    index -= 1

    def generate_reverse_halton_points(dimension, num_points):
        halton = Halton(dimension)

        points = []
        for _ in range(num_points):
            point = []

            vector = halton.next()
            while vector is not None:
                point.append(vector[0])
                vector = halton.next()

            if len(point) < dimension:
                raise ValueError(\"Insufficient number of points\")

            points.append(point)

        return points

    try:
        if dimension < 1 or dimension > 1229:
            raise ValueError(\"Invalid dimension\")

        points = generate_reverse_halton_points(dimension, num_points)
        result = json.dumps([point for point in points])

        return \"Candidate_solution\": %s\n" % result

