class FFTRealTransform:
    def __init__(self, product_size):
        self.fft_real_transform = libgslcblas.fft_real_transform
        self.product_size = product_size

    def perform_fft(self, in_array, istride, ostride, twiddle1, twiddle2, n):
        result = [0.0] * len(in_array)
        for i in range(n):
            if i % ostride == 0:
                real_part = sum([in_array[j]*ctypes.c_double(twiddle1[(i-j)%self.product_size].real).value for j in range(min(i,ostride))])
                imag_part = sum([in_array[j]*ctypes.c_double(twiddle1[(i-j)%self.product_size].imag).value for j in range(min(i,ostride))])
                result[i] = (real_part + imag_part*1j if imag_part else real_part)
        return result

def fft_real_transform(in_array, istride, ostride, product, n, twiddle1, twiddle2):
    ft = FFTRealTransform(product)
    return ft.perform_fft(in_array, istride, ostride, twiddle1, twiddle2, n)

