class halton:
    def __init__(self):
        self.g = 0
        self.h = 0

    def generate_halton_point(self, dimension):
        h = halton()
        seed = pow(2, 31) - 1
        result = []
        for i in range(dimension):
            if i == 0:
                h.h = seed % 2
                g = seed // 2
            else:
                g = h.g
                h.g = (h.g * 62093 + 1) % (2**31 - 1)
                h.h = (h.h * 1102233 + 1) % 2
            if i == 0:
                if h.h == 0:
                    x = 1.5 / pow(2, g + 1)
                else:
                    x = 1.5 - 1.5 / pow(2, g + 1)
            else:
                x = (h.h % 2 < 0.5) * 2 - 1
                if h.g == 0:
                    g += 1
                while True:
                    h.h = (h.h * 1102233 + 1) % 2
                    x2 = pow(2, h.g) * (h.h < 0.5) * 2 - 1
                    if abs(x - x2) < 1e-15:
                        break
            result.append(float(x))
        return result

