import numpy as np
from scipy.sparse import csr_matrix

def create_gsl_spmatrix():
    return ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    spmatrix = gsl.gsl_spmatrix
    return spmatrix

def perform_matrix_operation(spmatrices):
    A = csr_matrix([[1, 2], [3, 4]], dtype=np.int32)
    B = csr_matrix([[5, 6], [7, 8]], dtype=np.int32)
    C = np.zeros((2, 2), dtype=np.float64)

    # Create sparse matrices from numpy arrays.
    gsl_spmatrix_A = create_gsl_spmatrix()
    gsl_spmatrix_B = create_gsl_spmatrix()
    A_gsl = A.tocsc().astype(np.float32).tocoo()
    B_gsl = B.tocsc().astype(np.float32).tocoo()

    # Fill the GSL sparse matrices.
    for i in range(A_gsl.shape[0]):
        for j in range(A_gsl.shape[1]):
            if A_gsl[i, j] != 0:
                gsl_spmatrix_A.gsl_spmatrix_set_row(i, [j], [A_gsl[i, j]])
    for i in range(B_gsl.shape[0]):
        for j in range(B_gsl.shape[1]):
            if B_gsl[i, j] != 0:
                gsl_spmatrix_B.gsl_spmatrix_set_row(i, [j], [B_gsl[i, j]])

    # Perform matrix operation.
    result = np.zeros((2, 2), dtype=np.float64)
    for i in range(2):
        for j in range(2):
            for k in range(2):
                result[i, j] += A_gsl[i, k] * B_gsl[k, j]

    # Convert the result to a GSL sparse matrix.
    C_gsl = create_gsl_spmatrix()
    for i in range(C.shape[0]):
        for j in range(C.shape[1]):
            if result[i, j] != 0:
                C_gsl.gsl_spmatrix_set_row(i, [j], [result[i, j]])

    # Call the GSL function.
    gsl.gsl_blas_dgemm(gsl.gsl_matrix_transpose, A_gsl, B_gsl, C_gsl)

    return C

