# Define a class to represent GSL matrices
class GSLMatrix:
    def __init__(self, matrix):
        self.matrix = np.array(matrix)

    # Convert GSL matrix to NumPy array
    @staticmethod
    def gsl_matrix_to_numpy(gsl_matrix):
        return gsl_matrix.matrix

    # Convert NumPy array to GSL matrix
    @staticmethod
    def matrix_to_gsl(matrix):
        mat_ptr = ctypes.POINTER(ctypes.c_double * (len(matrix) * len(matrix[0])))
        for i in range(len(matrix)):
            for j in range(len(matrix[0])):
                mat_ptr[i][j] = matrix[i][j]
        return GSLMatrix(mat_ptr)

    # Compute the matrix exponential using GSL
    def compute_matrix_exponential(self, mode):
        n = len(self.matrix)
        cblas_matrix = self.matrix.ctypes.data_as(ctypes.POINTER(ctypes.c_double))
        result = ctypes.POINTER(ctypes.POINTER(ctypes.c_double))()
        gslcblas.gsl_linalg_exponential_ss(n, cblas_matrix, mode, byref(result))
        return GSLMatrix(result.contents)

    # Convert GSL matrix to NumPy array
    def __getattr__(self, name):
        if name == 'matrix':
            return self.gsl_matrix_to_numpy(self)
        elif name == 'gsl_matrix':
            return GSLMatrix.matrix_to_gsl(self)
