        gsl_matrix = gsl.gsl_matrix_alloc(n_rows, n_cols)
        for i in range(n_rows):
            for j in range(n_cols):
                gsl_matrix[i][j] = self.matrix[i][j].real + 1j * self.matrix[i][j].imag
        return gsl_matrix

    def from_gsl_matrix(self, gsl_matrix):
        n_rows = len(self.matrix)
        n_cols = len(self.matrix[0])
        for i in range(n_rows):
            for j in range(n_cols):
                self.matrix[i][j] = complex(gsl_matrix[i][j].real, gsl_matrix[i][j].imag)

