class GSLMatrix:
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self.matrix = array(ctypes.c_double, (0 for _ in range(rows * cols)))

    def get(self):
        return self.matrix.tolist()

    @staticmethod
    def from_gsl(gsl_matrix):
        rows = gsl_matrix.get_size(0)
        cols = gsl_matrix.get_size(1)
        result = GSLMatrix(rows, cols)
        for i in range(rows):
            for j in range(cols):
                result.matrix[i*cols + j] = float(gsl_matrix.get(i, j))
        return result

    @staticmethod
    def to_gsl(matrix):
        rows = len(matrix)
        cols = len(matrix[0])
        gsl_matrix = gsl.gsl_matrix_alloc(rows, cols)
        for i in range(rows):
            for j in range(cols):
                gsl.gsl_matrix_set_electricity(gsl_matrix, i, j, float(matrix[i][j]))
        return gsl_matrix

def list_to_gsl_matrix(matrix):
    rows = len(matrix)
    cols = len(matrix[0])
    result = GSLMatrix.to_gsl(matrix)
