import numpy as np

class GSLMatrix:
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols

    def _allocate(self):
        return (ctypes.c_double * (self.rows * self.cols))

    def to_numpy(self, array):
        return np.array([[array[i*self.cols+j] for j in range(self.cols)] for i in range(self.rows)])

    def free(self, array):
        del array

def list_to_ctypes_matrix(lst):
    mat = GSLMatrix(len(lst), len(lst[0]))
    mat._allocate()
    c_array = mat._allocate()
    for i in range(mat.rows):
        for j in range(mat.cols):
            c_array[i*mat.cols + j] = ctypes.c_double(lst[i][j])
    return c_array

