class GSLMatrix:
    def __init__(self, m, n):
        self.m = m
        self.n = n
        self.data = ctypes.c_double()
        libgslcblas.gsl_matrix_init(self.m, self.n, int(ctypes.sizeof(self.data) / ctypes.sizeof(ctypes.c_double())))
    def __del__(self):
        libgslcblas.gsl_matrix_free(self.m)

    def get(self):
        mat = []
        for i in range(self.m):
            row = []
            for j in range(self.n):
                row.append(ctypes.c_double.from_address(int(self.data) + (i * self.n + j) * ctypes.sizeof(ctypes.c_double())))
            mat.append(row)
        return json.dumps({'matrix': mat})

    def set(self, matrix):
        for i in range(len(matrix)):
            for j in range(len(matrix[i])):
                self.data.contents.value += (i * len(matrix) + j) * ctypes.sizeof(ctypes.c_double())
                ctypes.c_double.from_address(int(self.data) + (i * len(matrix) + j) * ctypes.sizeof(ctypes.c_double())).value = matrix[i][j]

    def create_and_manipulate_matrix():
        mat = GSLMatrix(2, 2)
        mat.set([[1.0, 2.0], [3.0, 4.0]])
        return mat.get()

