class GSLFunction:
    def __init__(self):
        self.gsl = ctypes.CDLL(\"/usr/local/gsl/lib/libgslcblas.so\", mode=ctypes.RTLD_GLOBAL)
        self.gsl = ctypes.CDLL(\"/usr/local/gsl/lib/libgsl.so\")

    def compute_derivative(self, func, x):
        func_ptr = ctypes.CFUNCTYPE(c_double, c_double)(func)
        x_val = ctypes.c_double(x)
        n_steps = 5
        h = (x / n_steps) * 0.5

        for i in range(n_steps):
            x_vals = [i * h]

            if i > 0:
                x_vals.append((i - 1) * h)
            if i < n_steps - 1:
                x_vals.append((i + 1) * h)

            x_val_ptr = (ctypes.c_double * len(x_vals))(*x_vals)
            res = self.gsl.gsl_diff_backward(len(x_vals), x_val_ptr, func_ptr, c_double(0))
            if i == 0:
                derivative = res
            else:
                derivative += res

        return derivative / n_steps

