def chebyshev_coefficients(order, func, a, b):
    series = gsl_cblas.gsl_cheb_series()
    series.set_interval(a, b)
    series.set_order(order)

    func_wrapper = gsl_function()
    func_wrapper.set_function(func)

    error_code = series.calculate_abscissa(c_double(0.5))
    if error_code != 0:
        raise Exception("Error calculating abscissa")

    coefficients = np.zeros((order + 1,))

    for i in range(order + 1):
        x = a + (b - a) * (np.cos(np.pi * i / order))
        y = func_wrapper.evaluate(x)

        error_code = series.calculate_coefficients(c_double(i), c_double(y))
        if error_code != 0:
            raise Exception("Error calculating coefficients")

    return coefficients.tolist()

