class PascalDistribution:
    def __init__(self, k, p):
        self.k = k
        self.p = p

    def cdf(self, n):
        return gsl.cdf_pascal_P(self.k, self.p, n) / math.factorial(self.k)**(n+1)

    def ccdf(self, n):
        return 1 - self.cdf(n)

def compute_pascal_cdf_and_ccdf(k, p, n):
    distribution = PascalDistribution(k, p)
    cdf = distribution.cdf(n)
    ccdf = distribution.ccdf(n)
