    _fields_ = [('data', ctypes.c_int32 * 3)]

def permutation_inverse(permutation):
    p = gsl_permutation()
    status = gsl.permutation_alloc(p)
    if status:
        raise Exception('gsl permutation allocation failed')
    for i in range(len(permutation)):
        p.data[i] = permutation[i]
    status = gsl.permutation_inverse(p)
    if status:
        raise Exception('gsl permutation inversion failed')
    inverse_perm = [0]*len(permutation)
    for i in range(len(permutation)):
        inverse_perm[p.data[i]] = i
    status = gsl.permutation_free(p)
    if status:
        raise Exception('gsl permutation free failed')
    return inverse_perm

