class GSLBlock:
    def __init__(self, n):
        self.n = c_int(n)

    @property
    def ptr(self):
        block_alloc_ptr_type = POINTER(c_void_p)
        return block_alloc_ptr_type()

    def allocate_and_free_block(self):
        block_alloc_func = gsl.gsl_block_alloc
        block_calloc_func = gsl.gsl_block_calloc
        block_free_func = gsl.gsl_block_free

        try:
            self.ptr.contents = block_calloc_func(self.n)
            for i in range(self.n.value):
                ptr_contents = self.ptr.contents[i]
                ptr_contents.value = 0
            block_free_func(self.ptr.contents)
