class GSLBlock:
    _memory_type = None
    def __init__(self, n):
        self.n = n
        self.block = gsl.gsl_block_alloc(n)
        if not self.block:
            raise Exception('gsl_block_alloc failed')
    def free(self):
        gsl.gsl_block_free(self.block)
        self.block = None
    def __del__(self):
        self.free()

    @classmethod
    def allocate_and_free_block(cls, n):
        block = cls(n)
        for i in range(block.n):
            block.block.data[i] = 0
        block.free()
        return True

