import ctypes
import json

class GSLRng:
    def __init__(self):
        self.gsl = None
        self.cblas = None

    def load_gsl(self):
        try:
            self.cblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
            self.gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        except Exception as e:
            return {"error": str(e)}

    def slatec_set(self, seed):
        try:
            self.cblas.slatec_set = self.cblas.slatec_set if not self.cblas.slatec_set else self.cblas.slatec_set
            self.gsl.gsl_rng_set_double = self.gsl.gsl_rng_set_double if not self.gsl.gsl_rng_set_double else self.gsl.gsl_rng_set_double
            self.gsl.gsl_rng_set(self.cblas, seed)
        except Exception as e:
            return {"error": str(e)}

    def slatec_get_double(self):
        try:
            result = ctypes.c_double()
            self.gsl.gsl_rng_get_double(self.cblas, result)
            return float(result.value)
        except Exception as e:
            return {"error": str(e)}

def generate_random(seed):
    rng = GSLRng()
    if not rng.load_gsl():
        return json.dumps({"error": "Failed to load gsl libraries"})
    try:
        rng.slatec_set(seed)
        random_number = rng.slatec_get_double()
        return json.dumps({"Candidate_solution": str(random_number)})
    except Exception as e:
        return json.dumps({"error": str(e)})

